local SS=game:GetService("ServerStorage") local r=SS:FindFirstChild("GoodRonnie") if not r then for _,d in ipairs(workspace:GetDescendants()) do if d:IsA("Model") and d.Name:lower():find("ronnie") and not d:GetAttribute("CharacterId") then r=d break end end end if not r then warn("No Ronnie model found in Workspace") else r.Name="GoodRonnie" r.Parent=SS local o1=game.ServerScriptService:FindFirstChild("RonnieSwap") if o1 then o1:Destroy() end local o2=game.StarterPlayer.StarterPlayerScripts:FindFirstChild("RonnieSwapClient") if o2 then o2:Destroy() end local s=Instance.new("Script") s.Name="RonnieSwap" s.Source=[==[local SS=game:GetService("ServerStorage") local YAW=0 local function swap(m) local good=SS:FindFirstChild("GoodRonnie") if not good then return end local hrp=m:WaitForChild("HumanoidRootPart",10) if not hrp then return end local cf,size=m:GetBoundingBox() local feet=cf.Position.Y-size.Y/2 local H=size.Y for _,d in ipairs(m:GetDescendants()) do if d:IsA("BasePart") or d:IsA("Decal") then d.Transparency=1 end end local g=good:Clone() g.Name="GoodRonnie" for _,d in ipairs(g:GetDescendants()) do if d:IsA("BaseScript") or d:IsA("Humanoid") then d:Destroy() end end local gcf,gs=g:GetBoundingBox() pcall(function() g:ScaleTo(g:GetScale()*H/gs.Y) end) gcf,gs=g:GetBoundingBox() local p=hrp.CFrame.Position local rot=(hrp.CFrame-p)*CFrame.Angles(0,math.rad(YAW),0) local box=CFrame.new(p.X,feet+gs.Y/2,p.Z)*rot*(gcf-gcf.Position) g:PivotTo(box*g:GetPivot():ToObjectSpace(gcf):Inverse()) local root=g:FindFirstChild("HumanoidRootPart") for _,d in ipairs(g:GetDescendants()) do if d:IsA("BasePart") then d.Anchored=false d.CanCollide=false d.CanQuery=false d.CanTouch=false d.Massless=true if not root then local w=Instance.new("WeldConstraint") w.Part0=hrp w.Part1=d w.Parent=d end end end if root then root.Transparency=1 local w=Instance.new("WeldConstraint") w.Part0=hrp w.Part1=root w.Parent=root end g.Parent=m end workspace.DescendantAdded:Connect(function(m) if m:IsA("Model") and m:GetAttribute("CharacterId")=="RonnieCurlman" then m:SetAttribute("MeshCharacter",nil) task.spawn(swap,m) end end)]==] s.Parent=game.ServerScriptService local c=Instance.new("LocalScript") c.Name="RonnieSwapClient" c.Source=[==[local RS=game:GetService("RunService") local list={} local function joints(root,skip) local t={} for _,d in ipairs(root:GetDescendants()) do if (d:IsA("Motor6D") or d:IsA("AnimationConstraint")) and not (skip and d:IsDescendantOf(skip)) then t[d.Name]=d end end return t end local function track(g) task.wait(0.5) local m=g.Parent if not m then return end local src,dst=joints(m,g),joints(g) local l={} for n,j in pairs(dst) do if src[n] then table.insert(l,{src[n],j}) end end list[g]=l end workspace.DescendantAdded:Connect(function(d) if d:IsA("Model") and d.Name=="GoodRonnie" and d.Parent and d.Parent:GetAttribute("CharacterId") then task.spawn(track,d) end end) RS.Heartbeat:Connect(function() for g,l in pairs(list) do if not g.Parent then list[g]=nil else for _,p in ipairs(l) do p[2].Transform=p[1].Transform end end end end)]==] c.Parent=game.StarterPlayer.StarterPlayerScripts print("GOOD RONNIE INSTALLED - press Play") end
